package tools

import (
	"bytes"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/cslsoftwares/mcpollama/mcp"
)

// CatalogHeader opens the generated TOOLS.md.
const CatalogHeader = "# TOOLS\n\n" +
	"<!-- Generated by `go run ./cmd/dumptools` from the tool registry. Do not edit by hand:\n" +
	"     tools.TestCatalogInSync fails when this file differs from the registry. -->\n\n"

func isFileTool(name string) bool {
	for _, n := range FileToolNames {
		if n == name {
			return true
		}
	}
	return false
}

// RenderCatalog renders TOOLS.md from tool definitions (BUILD-006). It is the
// single renderer: cmd/dumptools writes its output and the sync test compares
// against it. Output is deterministic: tools sorted by name, JSON with sorted
// keys, no timestamps.
func RenderCatalog(defs []mcp.Tool) string {
	sorted := append([]mcp.Tool(nil), defs...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })

	var b strings.Builder
	b.WriteString(CatalogHeader)
	fmt.Fprintf(&b, "%d tools. Tool names are a contract: renaming one is a breaking change.\n", len(sorted))
	for _, t := range sorted {
		fmt.Fprintf(&b, "\n## `%s`\n\n", t.Name)
		if t.Title != "" {
			fmt.Fprintf(&b, "**Title:** %s\n\n", t.Title)
		}
		fmt.Fprintf(&b, "%s\n\n", t.Description)
		if isFileTool(t.Name) {
			b.WriteString("Availability: registered only when the server starts with `--allow-root` (or `MCPOLLAMA_ALLOW_ROOT`); without it the tool does not exist and `tools/call` answers -32602.\n\n")
		}
		if a := t.Annotations; a != nil {
			fmt.Fprintf(&b, "Annotations: readOnlyHint=%t destructiveHint=%t idempotentHint=%t openWorldHint=%t\n\n",
				a.ReadOnlyHint, a.DestructiveHint, a.IdempotentHint, a.OpenWorldHint)
		}
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetEscapeHTML(false)
		enc.SetIndent("", "  ")
		if err := enc.Encode(t.InputSchema); err != nil {
			fmt.Fprintf(&b, "Input schema: (not serialisable: %v)\n", err)
			continue
		}
		b.WriteString("Input schema:\n\n```json\n")
		b.Write(buf.Bytes())
		b.WriteString("```\n")
	}
	return b.String()
}
